//autogenerated:yes
//nolint:revive,govet,errcheck
package common_test

import (
	"testing"

	dialectpkg "github.com/bluenviron/gomavlib/v4/pkg/dialects/common"
	"github.com/stretchr/testify/require"
)

func TestEnum_AIS_NAV_STATUS(t *testing.T) {
	t.Run("zero", func(t *testing.T) {
		var e dialectpkg.AIS_NAV_STATUS
		e.UnmarshalText([]byte{})
		e.MarshalText()
		e.String()
	})

	t.Run("first entry", func(t *testing.T) {
		enc, err := dialectpkg.AIS_NAV_STATUS_UNDER_WAY.MarshalText()
		require.NoError(t, err)

		var dec dialectpkg.AIS_NAV_STATUS
		err = dec.UnmarshalText(enc)
		require.NoError(t, err)

		require.Equal(t, dialectpkg.AIS_NAV_STATUS_UNDER_WAY, dec)
	})
}
